// ─── Validation helpers ─────────────────────────────────────────────────────
const VALID_WIDGET_TYPES = ['button', 'slider', 'toggle', 'display', 'input', 'knob', 'label'];
const VALID_CATEGORIES = ['navigation', 'media', 'data', 'settings', 'utility', 'auth', 'social'];
const VALID_ZONES = ['topbar', 'main', 'sidebar', 'bottom'];
const VALID_LAYOUTS = ['single-page', 'multi-page', 'dashboard', 'terminal'];
function validateWidgetType(t) {
    return VALID_WIDGET_TYPES.includes(t) ? t : 'button';
}
function validateCategory(c) {
    return VALID_CATEGORIES.includes(c) ? c : 'utility';
}
function validateZone(z, _index) {
    return VALID_ZONES.includes(z) ? z : 'main';
}
function validateLayout(l) {
    return VALID_LAYOUTS.includes(l) ? l : 'single-page';
}
function defaultPosition(index, axis, zone) {
    if (zone === 'topbar') {
        return axis === 'x' ? 30 + (index * 140) % 800 : 12;
    }
    if (zone === 'sidebar') {
        return axis === 'x' ? 20 : 60 + index * 50;
    }
    if (zone === 'bottom') {
        return axis === 'x' ? 30 + (index * 130) % 800 : 610;
    }
    // main zone
    return axis === 'x' ? 240 + (index * 30) % 600 : 80 + Math.floor(index / 5) * 90;
}
function defaultSize(type, dim) {
    const sizes = {
        button: { width: 120, height: 36 },
        slider: { width: 220, height: 28 },
        toggle: { width: 56, height: 28 },
        knob: { width: 52, height: 52 },
        display: { width: 280, height: 100 },
        input: { width: 220, height: 32 },
        label: { width: 120, height: 24 },
    };
    return sizes[type]?.[dim] || (dim === 'width' ? 120 : 36);
}
